/*
 * A085118  Primes together with twice the odd primes.
 * https://oeis.org/A085118
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 none, u16 none, u32 n <= 1000, u64 n <= 1000, u128 n <= 1000,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A085118: numbers that are prime or twice an odd prime. */

/* The sequence can be generated by taking all primes
   together with twice each odd prime.  The result is sorted in
   increasing order.  We build this list up to a fixed limit
   (200000) which is large enough to obtain at least 10000
   terms; the sequence is then indexed with a(1)=first term. */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

/* Helper comparison for qsort on seq_t elements */
static int seq_cmp(const void *a, const void *b)
{
    seq_t va = *(const seq_t *)a;
    seq_t vb = *(const seq_t *)b;
    if (va < vb) return -1;
    if (va > vb) return 1;
    return 0;
}

static bool init_done = false;
static seq_t *seq_array = NULL;   /* sorted list of the sequence values */
static size_t seq_len   = 0;      /* number of generated terms */

/* Build the sequence up to a fixed maximal value */
static void build_sequence(void)
{
    const uint64_t MAX_VAL = 200000ULL; /* sufficient for n up to ~10000 */
    /* Sieve of Eratosthenes to find all primes up to MAX_VAL */
    unsigned char *is_prime = (unsigned char *)malloc((MAX_VAL + 1) * sizeof(unsigned char));
    if (!is_prime) return;  /* memory failure: return; no sequence built */
    for (uint64_t i = 0; i <= MAX_VAL; ++i) is_prime[i] = 1;
    is_prime[0] = is_prime[1] = 0;
    for (uint64_t i = 2; i * i <= MAX_VAL; ++i)
        if (is_prime[i])
            for (uint64_t j = i * i; j <= MAX_VAL; j += i)
                is_prime[j] = 0;

    /* Count primes to allocate array */
    size_t prime_count = 0;
    for (uint64_t i = 2; i <= MAX_VAL; ++i)
        if (is_prime[i]) ++prime_count;

    /* Number of odd primes whose double is <= MAX_VAL is the number
       of primes <= MAX_VAL/2 excluding 2 */
    size_t double_prime_count = 0;
    for (uint64_t i = 3; i <= MAX_VAL / 2; ++i)
        if (is_prime[i]) ++double_prime_count;

    seq_len = prime_count + double_prime_count;
    seq_array = (seq_t *)malloc(seq_len * sizeof(seq_t));
    if (!seq_array) { free(is_prime); return; }

    /* Fill sequence array with primes and twice odd primes */
    size_t idx = 0;
    for (uint64_t i = 2; i <= MAX_VAL; ++i)
    {
        if (!is_prime[i]) continue;
        seq_array[idx++] = (seq_t)i;          /* the prime itself */
        if (i > 2 && 2 * i <= MAX_VAL)       /* twice an odd prime */
            seq_array[idx++] = (seq_t)i * 2;
    }

    /* Sort the resulting array */
    qsort(seq_array, seq_len, sizeof(seq_t), seq_cmp);

    free(is_prime);
    init_done = true;
}

seq_t a(idx_t n)
{
    if (!init_done) build_sequence();
    if (n == 0 || n > seq_len) return 0;   /* out of range – not expected in tests */
    return seq_array[n - 1];
}
